import re

from moler.exceptions import ParsingDone
from moler.helpers import update_dict

from ta_moler.events.emssim.genericemssim_textualevent import GenericEMSSIMTextualEvent


class AlarmReceived(GenericEMSSIMTextualEvent):
    """AlarmReceived event class."""

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """
        Event for 'Received Alarm'.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: runner to run command
        """
        super(AlarmReceived, self).__init__(connection=connection, runner=runner, till_occurs_times=till_occurs_times)
        self.current_ret = {}

    def on_new_line(self, line, is_full_line):
        """
        Parse output from EMSSIM.

        :param line: Line to parse, line is trimmed.
        :param is_full_line: True if new line character was removed from line, False otherwise.
        :return: None
        """
        if is_full_line:
            try:
                self._alarm_received(line)
                if self.current_ret:
                    self._alarm_body(line)
                    self._finish_alarm(line)
            except ParsingDone:
                pass

    # 09:14:19          |Received Alarm: 7653
    _re_received_alarm = re.compile(r"Received Alarm: (?P<RECEIVED_ALARM>\d+)")

    def _alarm_received(self, line):
        if self._regex_helper.search_compiled(AlarmReceived._re_received_alarm, line):
            alarm_id = self._regex_helper.group("RECEIVED_ALARM")
            if self.current_ret:
                self.logger.warning(f"New alarm '{alarm_id}' received but current_dict is not empty: '{self.current_ret}'")
                self.current_ret.clear()
            self.current_ret["ID"] = alarm_id
            raise ParsingDone()

    # 09:14:19          |***    ALARM:7653 "CELL FAULTY"
    _re_alarm = re.compile(r"ALARM:(?P<ALARM>\d+\s.*)")
    # 09:14:19          |       ACTIVITY=SET
    _re_activity = re.compile(r"ACTIVITY=(?P<ACTIVITY>\S+)")
    # 09:14:19          |       SEVERITY=CRITICAL
    _re_severity = re.compile(r"SEVERITY=(?P<SEVERITY>\S+)")
    # 09:14:19          |       EVENT_TIME=19-05-17 09:14:19 SEQUENCE=50
    _re_event_time_and_sequence = re.compile(r"EVENT_TIME=(?P<EVENT_TIME>\d\d-\d\d-\d\d\s\d\d:\d\d:\d\d)\sSEQUENCE=(?P<SEQUENCE>\d+)")
    # 09:14:19          |       EVENT_TYPE="Quality Of Service"
    _re_event_type = re.compile(r"EVENT_TYPE=\"(?P<EVENT_TYPE>.*)\"")
    # r"09:14:19          |       FAULT_ID=23"
    _re_fault_id = re.compile(r"FAULT_ID=(?P<FAULT_ID>\S+)")
    # 09:14:19          |       ALARM_TEXT="Incompatible SW version detected"
    _re_alarm_text = re.compile(r"ALARM_TEXT=\"(?P<ALARM_TEXT>.*)\"")
    # 09:14:19          |       ADDITIONAL_INFO="<shared>N</shared><additionalFaultId>23</additionalFaultId>"
    _re_additional_info = re.compile(r"ADDITIONAL_INFO=\"(?P<ADDITIONAL_INFO>.*)\"")

    _re_alarm_body = (
        _re_alarm,
        _re_activity,
        _re_severity,
        _re_event_time_and_sequence,
        _re_event_type,
        _re_fault_id,
        _re_alarm_text,
        _re_additional_info,
    )

    def _alarm_body(self, line):
        for regex in AlarmReceived._re_alarm_body:
            if self._regex_helper.search_compiled(regex, line):
                update_dict(self.current_ret, self._regex_helper.groupdict())
                raise ParsingDone()

    #  #A
    _re_alarm_finsh = re.compile(r"#A")

    def _finish_alarm(self, line):
        if self._regex_helper.search_compiled(AlarmReceived._re_alarm_finsh, line):
            self.event_occurred(event_data=self.current_ret)
            self.current_ret = {}
            raise ParsingDone()


